import { db } from "@acme/db";
import { NextResponse } from "next/server";
import { withWorkspace } from "@/lib/auth";

export async function GET(req: Request) {
  const workspaceId = new URL(req.url).pathname.split("/")[3];
  const rows = await db.link.findMany({ where: { workspaceId, archived: false }, orderBy: { createdAt: "desc" } });
  return NextResponse.json(rows);
}

export const POST = withWorkspace(async (req, { workspaceId }) => {
  const body = await req.json();
  return NextResponse.json(await db.link.create({ data: { ...body, workspaceId } }));
}, { requiredPermissions: ["links.write"] });
